    /** Species names exactly as printed, in table order. */
    val species: List<String> = rows.map { it.species }.distinct()

    fun find(species: String, grade: String, sizeClassification: String, agency: String): Row? =
        rows.firstOrNull {
            it.species == species && it.grade == grade && it.sizeClassification == sizeClassification &&
                agency in it.gradingRulesAgencies
        }
}
